<?php
require_once __DIR__ . '/bootstrap.php';
try {
    $loan = $lending->loan((int) ($_GET['id'] ?? 0));
    $activity = $lending->activity((int) $loan['loan_id']);
} catch (OutOfBoundsException $error) { http_response_code(404); exit(t('Loan not found.')); }
$title = t('Loan #') . $loan['loan_id'];
$canPost = in_array($user['role_name'], ['SUPER_ADMIN','ACCOUNTANT'], true);
$canRecover = in_array($user['role_name'], ['SUPER_ADMIN','RECOVERY_OFFICER'], true);
require __DIR__ . '/../includes/header.php';
?>
<div class="page-heading"><div><span class="eyebrow"><?= e(t('Loan #')) ?><?= e($loan['loan_id']) ?> · <?= e($loan['product_name']) ?></span><h1><?= e($loan['full_name']) ?></h1><p><?= e($loan['phone_number']) ?> · <?= e($loan['term_months']) ?> <?= e(t('monthly installments')) ?></p></div><?= status_badge($loan['display_status']) ?></div>
<div class="portal-grid"><section class="card loan-overview"><span class="eyebrow"><?= e(t('Outstanding balance')) ?></span><div class="balance-value"><?= e(format_number((float) $loan['outstanding_balance_rwf'], 2)) ?> <small>RWF</small></div><dl class="detail-list detail-columns"><?php foreach (['principal_amount_rwf'=>t('Principal'),'interest_amount_rwf'=>t('Agreed interest'),'total_payable_rwf'=>t('Total payable'),'disbursement_date'=>t('Disbursed on'),'maturity_date'=>t('Maturity date')] as $key=>$label): ?><div><dt><?= e(t($label)) ?></dt><dd><?= e(str_ends_with($key,'_rwf') ? money($loan[$key]) : ($loan[$key] ? format_date($loan[$key]) : t('Awaiting disbursement'))) ?></dd></div><?php endforeach; ?><div><dt><?= e(t('Interest rate')) ?></dt><dd><?= e(format_number($loan['interest_rate_pct'], 2)) ?><?= e(t('% flat, applied once')) ?></dd></div></dl><?php if ($activity['disbursement']): ?><p class="help"><?= e(t('Disbursement reference:')) ?> <?= e($activity['disbursement']['external_reference']) ?> · <?= e(enum_label($activity['disbursement']['payment_method'])) ?></p><?php endif; ?></section>
<?php if ($canPost && ($loan['status'] === 'APPROVED' || in_array($loan['status'], LendingService::LIVE, true))): $operation = $loan['status'] === 'APPROVED' ? 'disburse' : 'payment'; ?>
<aside class="card"><h2><?= $operation === 'disburse' ? t('Record disbursement') : t('Post a repayment') ?></h2><form method="POST" action="<?= e(app_url('workspace/action.php')) ?>"><?= csrf_field() ?><?= form_nonce($operation . '_' . $loan['loan_id']) ?><input type="hidden" name="action" value="<?= e($operation) ?>"><input type="hidden" name="id" value="<?= e($loan['loan_id']) ?>"><?php if ($operation === 'payment'): ?><div class="field"><label for="amount"><?= e(t('Amount received (RWF)')) ?></label><input id="amount" type="number" name="amount" min="0.01" max="<?= e($loan['outstanding_balance_rwf']) ?>" step="0.01" required></div><?php else: ?><p class="help"><?= e(t('Record the full principal of')) ?> <?= e(money($loan['principal_amount_rwf'])) ?> <?= e(t('after funds have been transferred.')) ?></p><?php endif; ?><div class="field"><label for="date"><?= e(t('Transaction date')) ?></label><input id="date" name="date" type="date" max="<?= e(date('Y-m-d')) ?>" value="<?= e(date('Y-m-d')) ?>" required></div><div class="field"><label for="method"><?= e(t('Payment method')) ?></label><select id="method" name="method"><?php foreach (LendingService::METHODS as $key=>$label): ?><option value="<?= e($key) ?>"><?= e(t($label)) ?></option><?php endforeach; ?></select></div><div class="field"><label for="reference"><?= e(t('Unique transaction reference')) ?></label><input id="reference" name="reference" minlength="6" maxlength="80" placeholder="<?= e(t('Bank, mobile money, or cash reference')) ?>" required></div><button class="button wide"><?= $operation === 'disburse' ? t('Record disbursement') : t('Post confirmed repayment') ?></button></form></aside>
<?php else: ?><aside class="card dark-card"><span class="eyebrow"><?= e(t('Loan progress')) ?></span><h2><?= e(t('Every detail.')) ?><br><?= e(t('One clear view.')) ?></h2><p><?= e(t('See the monthly schedule, confirmed payments, and status changes below.')) ?></p><a class="button" href="<?= e(app_url('workspace/index.php?tab=loans')) ?>"><?= e(t('Back to portfolio →')) ?></a></aside><?php endif; ?></div>
<?php require __DIR__ . '/../view/loans/activity.php'; ?>
<?php if (in_array($user['role_name'], ['SUPER_ADMIN','MANAGER','RECOVERY_OFFICER'], true)): ?>
<section class="card spaced"><h2><?= e(t('Recovery contact history')) ?></h2><?php foreach ($lending->recoveryLogs((int) $loan['loan_id']) as $log): ?><article class="contact-log"><strong><?= e(enum_label($log['contact_type'])) ?></strong><span class="cell-note"><?= e(format_date($log['logged_at'], true)) ?> · <?= e($log['full_name']) ?></span><p class="preserve-lines"><?= e($log['summary_notes']) ?></p><p class="help"><?= e(t('Promised payment:')) ?> <?= e(format_date($log['promised_payment_date'])) ?> <?= e(t('· Next follow-up:')) ?> <?= e(format_date($log['next_followup_date'])) ?></p></article><?php endforeach; ?>
<?php if ($canRecover && $loan['display_status'] === 'OVERDUE'): ?><form method="POST" action="<?= e(app_url('workspace/action.php')) ?>"><?= csrf_field() ?><?= form_nonce('recovery_' . $loan['loan_id']) ?><input type="hidden" name="action" value="recovery"><input type="hidden" name="id" value="<?= e($loan['loan_id']) ?>"><div class="field"><label for="contact"><?= e(t('Contact method')) ?></label><select id="contact" name="contact_type"><?php foreach (['PHONE_CALL','PHYSICAL_VISIT','SMS','WARNING_LETTER'] as $method): ?><option value="<?= e($method) ?>"><?= e(enum_label($method)) ?></option><?php endforeach; ?></select></div><div class="field"><label for="notes"><?= e(t('Contact notes')) ?></label><textarea id="notes" name="notes" maxlength="3000" required></textarea></div><div class="row"><div class="field"><label for="promise"><?= e(t('Promised payment date')) ?></label><input id="promise" name="promised_date" type="date"></div><div class="field"><label for="followup"><?= e(t('Next follow-up date')) ?></label><input id="followup" name="followup_date" type="date"></div></div><button class="button"><?= e(t('Save contact log')) ?></button></form><?php endif; ?></section><?php endif; ?>
